import { useState } from "react"

import { EmptyState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { useCollection } from "@/lib/mini/store"
import { cn } from "@/lib/utils"

import { Inspector } from "./index"
import type { InspectorItem, InspectorSchema } from "./index"

type PosterItem = InspectorItem & {
  type: "frame" | "text" | "shape"
  x: number
  y: number
  w: number
  h: number
  fill?: string
  text?: string
  fontSize?: number
  align?: string
  shadow?: boolean
  blur?: number
}

const FILLS = [
  { value: "background", label: "Background" },
  { value: "card", label: "Card" },
  { value: "muted", label: "Muted" },
  { value: "secondary", label: "Secondary" },
  { value: "accent", label: "Accent" },
  { value: "primary", label: "Primary" },
]

const frame = (
  id: string,
  title: string,
  parentId: string | null,
  x: number,
  y: number,
  w: number,
  h: number,
  fill: string
): PosterItem => ({ id, title, type: "frame", parentId, x, y, w, h, fill })

const text = (
  id: string,
  title: string,
  parentId: string,
  x: number,
  y: number,
  w: number,
  h: number,
  copy: string,
  fontSize: number
): PosterItem => ({
  id,
  title,
  type: "text",
  parentId,
  x,
  y,
  w,
  h,
  text: copy,
  fontSize,
  align: "left",
})

const shape = (
  id: string,
  title: string,
  parentId: string,
  x: number,
  y: number,
  w: number,
  h: number,
  fill: string
): PosterItem => ({ id, title, type: "shape", parentId, x, y, w, h, fill })

const seed: PosterItem[] = [
  frame("poster", "Open Studio Poster", null, 0, 0, 320, 440, "card"),
  frame("header", "Header", "poster", 0, 0, 320, 104, "muted"),
  text("title", "Title", "header", 20, 16, 232, 40, "Open Studio Weekend", 22),
  text(
    "subtitle",
    "Subtitle",
    "header",
    20,
    62,
    220,
    24,
    "Painters, potters and printmakers",
    12
  ),
  shape("mark", "Corner mark", "header", 252, 20, 48, 48, "primary"),
  shape("photo", "Photo", "poster", 20, 124, 280, 164, "accent"),
  text(
    "caption",
    "Caption: work in progress from the north-light studio on the second floor, shown by kind permission",
    "poster",
    20,
    298,
    280,
    36,
    "Work in progress from the north-light studio",
    11
  ),
  frame("footer", "Footer", "poster", 0, 356, 320, 84, "muted"),
  text("date", "Date", "footer", 20, 372, 140, 24, "12 and 13 April", 14),
  text(
    "venue",
    "Venue",
    "footer",
    20,
    400,
    200,
    20,
    "The Mill, Canal Street",
    11
  ),
  shape("badge", "Free entry badge", "footer", 244, 372, 56, 56, "secondary"),
  shape("rule", "Divider", "poster", 20, 342, 280, 4, "primary"),
  frame("back", "Back page", null, 344, 0, 320, 440, "card"),
  text(
    "map",
    "Map note",
    "back",
    364,
    20,
    280,
    60,
    "Parking is behind the mill. Step-free entrance on the east side.",
    13
  ),
]

const schema: InspectorSchema<PosterItem> = {
  frame: [positionSection(), layoutSection(), fillSection(), shadowSection()],
  text: [
    positionSection(),
    layoutSection(),
    {
      id: "text",
      title: "Text",
      fields: [
        { key: "text", label: "Content", kind: "text" },
        {
          key: "fontSize",
          label: "Size",
          kind: "number",
          unit: "px",
          min: 8,
          max: 96,
        },
        {
          key: "align",
          label: "Align",
          kind: "select",
          options: [
            { value: "left", label: "Left" },
            { value: "center", label: "Center" },
            { value: "right", label: "Right" },
          ],
        },
      ],
    },
    shadowSection(),
  ],
  shape: [positionSection(), layoutSection(), fillSection(), shadowSection()],
}

function positionSection() {
  return {
    id: "position",
    title: "Position",
    fields: [
      { key: "x", label: "X", kind: "number", unit: "px" },
      { key: "y", label: "Y", kind: "number", unit: "px" },
    ],
  } satisfies InspectorSchema<PosterItem>["frame"][number]
}

function layoutSection() {
  return {
    id: "layout",
    title: "Layout",
    fields: [
      { key: "w", label: "W", kind: "number", unit: "px", min: 0 },
      { key: "h", label: "H", kind: "number", unit: "px", min: 0 },
    ],
  } satisfies InspectorSchema<PosterItem>["frame"][number]
}

function fillSection() {
  return {
    id: "fill",
    title: "Fill",
    fields: [
      {
        key: "fill",
        label: "Color",
        kind: "popover",
        renderEditor: (value, set) => (
          <div
            role="group"
            aria-label="Fill color"
            className="grid grid-cols-3 gap-1.5"
          >
            {FILLS.map((fill) => (
              <button
                key={fill.value}
                type="button"
                aria-pressed={value === fill.value}
                onClick={() => set(fill.value)}
                className={cn(
                  "flex flex-col items-center gap-1 rounded-md p-1.5 text-xs outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring",
                  value === fill.value && "bg-muted font-medium"
                )}
              >
                <span
                  aria-hidden
                  className="size-8 rounded-md border"
                  style={{ background: `var(--${fill.value})` }}
                />
                {fill.label}
              </button>
            ))}
          </div>
        ),
      },
    ],
  } satisfies InspectorSchema<PosterItem>["frame"][number]
}

function shadowSection() {
  return {
    id: "shadow",
    title: "Shadow",
    optional: true,
    fields: [
      { key: "shadow", label: "Drop shadow", kind: "toggle" },
      {
        key: "blur",
        label: "Blur",
        kind: "number",
        unit: "px",
        min: 0,
        max: 40,
      },
    ],
  } satisfies InspectorSchema<PosterItem>["frame"][number]
}

const PREVIEW_ERROR = new Error(
  "Preview only: the inspector-demo collection could not be read."
)

type Preview = "live" | "empty" | "loading" | "error"
const PREVIEWS: Preview[] = ["live", "empty", "loading", "error"]

function Canvas({
  items,
  selectedIds,
  hoverId,
  select,
  hover,
}: {
  items: PosterItem[]
  selectedIds: string[]
  hoverId: string | null
  select: (id: string, mode: "replace" | "toggle") => void
  hover: (id: string | null) => void
}) {
  return (
    <div className="relative h-[480px] w-[704px] p-4">
      {items.map((item) => {
        const isSelected = selectedIds.includes(item.id)
        const isHover = hoverId === item.id
        const left = 16 + item.x
        const top = 16 + item.y
        return (
          <div
            key={item.id}
            role="button"
            tabIndex={0}
            aria-label={`${item.title}, ${item.type}`}
            aria-pressed={isSelected}
            onClick={(event) =>
              select(
                item.id,
                event.metaKey || event.ctrlKey ? "toggle" : "replace"
              )
            }
            onKeyDown={(event) => {
              if (event.key === " ") {
                event.preventDefault()
                select(item.id, "replace")
              } else if (event.key === "Enter") {
                select(item.id, "replace")
              }
            }}
            onPointerEnter={() => hover(item.id)}
            onPointerLeave={() => hover(null)}
            style={{
              position: "absolute",
              left,
              top,
              width: item.w,
              height: item.h,
              background:
                item.type === "text"
                  ? "transparent"
                  : `var(--${item.fill ?? "muted"})`,
              boxShadow: item.shadow
                ? `0 ${(item.blur ?? 8) / 2}px ${item.blur ?? 8}px rgb(0 0 0 / 0.3)`
                : undefined,
              fontSize: item.fontSize,
              textAlign: item.align as "left" | "center" | "right" | undefined,
            }}
            className={cn(
              "cursor-default overflow-hidden leading-tight outline-none select-none",
              item.type === "frame" && "border",
              isHover && !isSelected && "outline outline-1 outline-primary/50",
              isSelected && "outline outline-2 outline-primary",
              "focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            {item.type === "text" ? item.text : null}
            {isSelected ? (
              <span className="pointer-events-none absolute right-0 bottom-0 rounded-tl bg-primary px-1 text-[10px] leading-4 text-primary-foreground">
                {item.w} x {item.h}
              </span>
            ) : null}
          </div>
        )
      })}
    </div>
  )
}

function PageView({ items }: { items: PosterItem[] }) {
  const count = (type: PosterItem["type"]) =>
    items.filter((item) => item.type === type).length
  return (
    <div className="flex flex-col gap-3">
      <dl className="grid grid-cols-3 gap-1.5 text-center text-xs">
        {(["frame", "text", "shape"] as const).map((type) => (
          <div key={type} className="rounded-md bg-muted p-2">
            <dt className="text-muted-foreground capitalize">{type}s</dt>
            <dd className="text-sm font-semibold">{count(type)}</dd>
          </div>
        ))}
      </dl>
      <p className="text-xs text-muted-foreground">
        Select a layer in the tree or on the canvas to edit it. Use Shift or
        Ctrl click to select several.
      </p>
    </div>
  )
}

export default function Demo() {
  const collection = useCollection<PosterItem>("inspector-demo", seed)
  const [preview, setPreview] = useState<Preview>("live")

  const status =
    preview === "loading" || preview === "error" ? preview : collection.status
  const items = preview === "empty" ? [] : collection.items

  const addFrame = async () => {
    await collection.add(
      frame(crypto.randomUUID(), "New frame", null, 0, 0, 200, 120, "card")
    )
    setPreview("live")
  }

  return (
    <div className="flex h-full min-h-[34rem] flex-col">
      <div className="flex shrink-0 flex-wrap items-center gap-2 border-b px-3 py-1.5">
        <span
          id="inspector-demo-preview"
          className="text-xs text-muted-foreground"
        >
          Preview state
        </span>
        <div
          role="group"
          aria-labelledby="inspector-demo-preview"
          className="flex gap-1"
        >
          {PREVIEWS.map((option) => (
            <Button
              key={option}
              size="xs"
              variant={preview === option ? "secondary" : "outline"}
              aria-pressed={preview === option}
              onClick={() => setPreview(option)}
              className="capitalize"
            >
              {option}
            </Button>
          ))}
        </div>
        <Button
          size="xs"
          variant="ghost"
          className="ml-auto"
          onClick={() => {
            setPreview("live")
            void collection.replaceAll(seed)
          }}
        >
          Reset sample data
        </Button>
      </div>
      <div className="min-h-0 flex-1">
        <Inspector
          items={items}
          schema={schema}
          status={status}
          error={preview === "error" ? PREVIEW_ERROR : collection.error}
          onRetry={() => setPreview("live")}
          onUpdate={async (ids, patch) => {
            await Promise.all(ids.map((id) => collection.update(id, patch)))
          }}
          onRemove={async (ids) => {
            await Promise.all(ids.map((id) => collection.remove(id)))
          }}
          onRename={(id, title) => collection.update(id, { title })}
          renderCanvas={(ctx) => <Canvas {...ctx} />}
          pageView={<PageView items={items} />}
          emptyView={
            <EmptyState
              title="No layers yet"
              description="Add a frame to start laying out a poster."
              action={
                <Button size="sm" onClick={() => void addFrame()}>
                  Add frame
                </Button>
              }
            />
          }
        />
      </div>
    </div>
  )
}

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { PanelLeftIcon, PanelRightIcon } from "lucide-react"
import { toast } from "sonner"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Kbd } from "@/components/ui/kbd"
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

import { ItemTree } from "./item-tree"
import { PropertiesPanel } from "./properties-panel"
import { buildRows } from "./tree-model"
import type { InspectorItem, InspectorProps, SelectMode } from "./types"

const UNDO_MS = 5000
const EMPTY_SET: ReadonlySet<string> = new Set()
const PANEL_FIELDS =
  '[data-region="panel"] [data-panel-body] :is(input, [role="combobox"], [role="checkbox"], button):not(:disabled)'

type Overlay<T> = { token: number; ids: string[]; patch: Partial<T> }

function describeError(cause: unknown) {
  return cause instanceof Error ? cause.message : String(cause)
}

function DockToggle({
  label,
  shortcut,
  pressed,
  onClick,
  children,
}: {
  label: string
  shortcut?: string
  pressed: boolean
  onClick: () => void
  children: ReactNode
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={label}
          aria-pressed={pressed}
          onClick={onClick}
        >
          {children}
        </Button>
      </TooltipTrigger>
      <TooltipContent>
        {label}
        {shortcut ? <Kbd className="ml-2">{shortcut}</Kbd> : null}
      </TooltipContent>
    </Tooltip>
  )
}

function Workspace<T extends InspectorItem>({
  items: sourceItems,
  schema,
  selectedIds: controlledIds,
  onSelectionChange,
  onUpdate,
  onRemove,
  onRename,
  renderCanvas,
  pageView,
  emptyView,
}: InspectorProps<T>) {
  const [ownIds, setOwnIds] = useState<string[]>([])
  const [hoverId, setHoverId] = useState<string | null>(null)
  const [leftOpen, setLeftOpen] = useState(true)
  const [rightOpen, setRightOpen] = useState(true)
  const [allHidden, setAllHidden] = useState(false)
  const [removing, setRemoving] = useState<ReadonlySet<string>>(EMPTY_SET)
  const [overlays, setOverlays] = useState<Overlay<T>[]>([])
  const [anchorId, setAnchorId] = useState<string | null>(null)
  const canvasEl = useRef<HTMLDivElement>(null)
  const tokens = useRef(0)
  const finalizers = useRef(new Set<() => void>())

  // optimistic edits and not-yet-committed removals sit over the app's items so the UI never flashes stale values
  const items = useMemo(() => {
    if (removing.size === 0 && overlays.length === 0) return sourceItems
    return sourceItems
      .filter((item) => !removing.has(item.id))
      .map((item) =>
        overlays.reduce(
          (acc, overlay) =>
            overlay.ids.includes(item.id) ? { ...acc, ...overlay.patch } : acc,
          item
        )
      )
  }, [sourceItems, removing, overlays])

  const byId = useMemo(
    () => new Map(items.map((item) => [item.id, item])),
    [items]
  )
  const orderedIds = useMemo(
    () => buildRows(items, EMPTY_SET).map((row) => row.item.id),
    [items]
  )
  const rawIds = controlledIds ?? ownIds
  const selectedIds = useMemo(
    () => rawIds.filter((id) => byId.has(id)),
    [rawIds, byId]
  )
  const selected = useMemo(
    () => selectedIds.flatMap((id) => byId.get(id) ?? []),
    [selectedIds, byId]
  )

  const setSelection = useCallback(
    (ids: string[]) => {
      if (controlledIds === undefined) setOwnIds(ids)
      onSelectionChange?.(ids)
    },
    [controlledIds, onSelectionChange]
  )

  const select = (id: string, mode: SelectMode) => {
    setAnchorId(id)
    if (mode === "toggle") {
      setSelection(
        selectedIds.includes(id)
          ? selectedIds.filter((x) => x !== id)
          : [...selectedIds, id]
      )
    } else {
      setSelection([id])
    }
  }

  const selectFromTree = (
    id: string,
    mode: "replace" | "range" | "toggle",
    visibleIds: string[]
  ) => {
    if (mode !== "range") return select(id, mode)
    const from = visibleIds.indexOf(anchorId ?? selectedIds.at(-1) ?? id)
    const to = visibleIds.indexOf(id)
    if (from < 0 || to < 0) return select(id, "replace")
    setSelection(visibleIds.slice(Math.min(from, to), Math.max(from, to) + 1))
  }

  const write = useCallback(
    async (
      ids: string[],
      patch: Partial<T>,
      task: () => void | Promise<void>,
      failure: string
    ) => {
      const token = ++tokens.current
      setOverlays((prev) => [...prev, { token, ids, patch }])
      try {
        await task()
      } catch (cause) {
        toast.error(failure, { description: describeError(cause) })
      } finally {
        setOverlays((prev) => prev.filter((overlay) => overlay.token !== token))
      }
    },
    []
  )

  const update = (patch: Partial<T>) => {
    const ids = selectedIds
    void write(ids, patch, () => onUpdate(ids, patch), "Could not save changes")
  }

  const rename = onRename
    ? (id: string, title: string) =>
        void write(
          [id],
          { title } as unknown as Partial<T>,
          () => onRename(id, title),
          "Could not rename"
        )
    : undefined

  const removeSelected = (root: HTMLElement | null, restoreFocus: boolean) => {
    if (!onRemove || selectedIds.length === 0) return
    const ids = selectedIds
    const gone = new Set(ids)
    const remaining = orderedIds.filter((id) => !gone.has(id))
    const firstIndex = Math.min(...ids.map((id) => orderedIds.indexOf(id)))
    const focusTarget = remaining[Math.min(firstIndex, remaining.length - 1)]

    setRemoving((prev) => new Set([...prev, ...ids]))
    setSelection([])
    if (restoreFocus && focusTarget !== undefined) {
      requestAnimationFrame(() =>
        root
          ?.querySelector<HTMLElement>(
            `[data-region="tree"] [data-item-id="${CSS.escape(focusTarget)}"]`
          )
          ?.focus()
      )
    }

    const release = () =>
      setRemoving((prev) => new Set([...prev].filter((id) => !gone.has(id))))
    const finalize = () => {
      window.clearTimeout(timer)
      finalizers.current.delete(finalize)
      toast.dismiss(toastId)
      void (async () => {
        try {
          await onRemove(ids)
        } catch (cause) {
          toast.error("Could not remove", { description: describeError(cause) })
        } finally {
          release()
        }
      })()
    }
    const timer = window.setTimeout(finalize, UNDO_MS)
    finalizers.current.add(finalize)

    const first = byId.get(ids[0])?.title ?? "item"
    const toastId = toast(
      ids.length === 1 ? `Removed "${first}"` : `Removed ${ids.length} items`,
      {
        duration: UNDO_MS,
        action: {
          label: "Undo",
          onClick: () => {
            window.clearTimeout(timer)
            finalizers.current.delete(finalize)
            release()
            setSelection(ids)
          },
        },
      }
    )
  }

  useEffect(() => {
    const pending = finalizers.current
    return () => [...pending].forEach((finalize) => finalize())
  }, [])

  const rootRef = useHotkeys<HTMLDivElement>(
    ["escape", "delete", "backspace", "enter", "meta+a", "ctrl+a"],
    (event) => {
      const root = event.currentTarget
      const target = event.target
      if (!(root instanceof HTMLElement) || !(target instanceof Element)) return
      const inTree = target.closest('[data-region="tree"]') !== null
      if (!inTree && target.closest('[data-region="canvas"]') === null) return

      if (event.key === "Enter") {
        if (!inTree) return
        event.preventDefault()
        const field = root.querySelector<HTMLElement>(PANEL_FIELDS)
        field?.focus()
        if (field instanceof HTMLInputElement) field.select()
      } else if (event.key === "Escape") {
        if (selectedIds.length > 0) setSelection([])
      } else if (event.key === "Delete" || event.key === "Backspace") {
        event.preventDefault()
        removeSelected(root, inTree)
      } else {
        event.preventDefault()
        setSelection(orderedIds)
      }
    }
  )

  useHotkeys("shift+backslash", () => {
    setAllHidden(!allHidden)
    // hiding the tree can drop focus on the body, where Esc and Delete no longer reach the workspace
    if (!allHidden) {
      requestAnimationFrame(() => {
        if (document.activeElement === document.body) canvasEl.current?.focus()
      })
    }
  })

  const onPanelKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const target = event.target
    if (event.key !== "Escape" || !(target instanceof HTMLInputElement)) return
    if (!event.currentTarget.contains(target)) return
    const primary = selectedIds.at(-1)
    if (primary === undefined) return
    event.currentTarget
      .closest<HTMLElement>("[data-inspector]")
      ?.querySelector<HTMLElement>(
        `[data-region="tree"] [data-item-id="${CSS.escape(primary)}"]`
      )
      ?.focus()
  }

  const showLeft = leftOpen && !allHidden
  const showRight = rightOpen && (!allHidden || selectedIds.length > 0)
  const toggleLeft = () => {
    if (allHidden) setAllHidden(false)
    setLeftOpen(allHidden ? true : !leftOpen)
  }
  const toggleRight = () => {
    if (allHidden) setAllHidden(false)
    setRightOpen(allHidden ? true : !rightOpen)
  }

  const hoverFromTree = (target: EventTarget) => {
    const id =
      target instanceof Element
        ? target.closest<HTMLElement>("[data-item-id]")?.dataset.itemId
        : undefined
    setHoverId(id ?? null)
  }

  return (
    <div
      ref={rootRef}
      data-inspector
      className="flex h-full min-h-0 flex-col bg-background"
    >
      <div className="flex h-9 shrink-0 items-center gap-1 border-b px-2">
        <DockToggle
          label="Toggle item tree"
          pressed={showLeft}
          onClick={toggleLeft}
        >
          <PanelLeftIcon />
        </DockToggle>
        <DockToggle
          label="Toggle properties panel"
          pressed={showRight}
          onClick={toggleRight}
        >
          <PanelRightIcon />
        </DockToggle>
        <span className="ml-auto text-xs text-muted-foreground">
          Hide docks <Kbd>⇧</Kbd> <Kbd>\</Kbd>
        </span>
      </div>
      <ResizablePanelGroup orientation="horizontal" className="min-h-0 flex-1">
        {showLeft ? (
          <>
            <ResizablePanel
              id="tree"
              defaultSize="20%"
              minSize="140px"
              maxSize="40%"
            >
              <div
                data-region="tree"
                className="h-full min-h-0"
                onPointerOver={(event) => hoverFromTree(event.target)}
                onPointerLeave={() => setHoverId(null)}
              >
                {items.length === 0 ? (
                  <EmptyState title="No items" />
                ) : (
                  <ItemTree
                    items={items}
                    selectedIds={selectedIds}
                    onSelect={selectFromTree}
                    onRename={rename}
                  />
                )}
              </div>
            </ResizablePanel>
            <ResizableHandle />
          </>
        ) : null}
        <ResizablePanel id="canvas" minSize="20%">
          <div
            ref={canvasEl}
            data-region="canvas"
            role="region"
            aria-label="Canvas"
            tabIndex={-1}
            className="relative h-full min-w-0 overflow-auto outline-none"
          >
            {items.length === 0
              ? (emptyView ?? <EmptyState title="Nothing to inspect yet" />)
              : renderCanvas({
                  items,
                  selectedIds,
                  hoverId,
                  select,
                  hover: setHoverId,
                })}
          </div>
        </ResizablePanel>
        {showRight ? (
          <>
            <ResizableHandle />
            <ResizablePanel
              id="panel"
              defaultSize="22%"
              minSize="200px"
              maxSize="45%"
            >
              <div
                data-region="panel"
                data-mini="panel"
                role="region"
                aria-label="Properties"
                className="h-full min-h-0"
                onKeyDown={onPanelKeyDown}
              >
                <PropertiesPanel
                  selected={selected}
                  schema={schema}
                  onChange={update}
                  pageView={pageView}
                />
              </div>
            </ResizablePanel>
          </>
        ) : null}
      </ResizablePanelGroup>
    </div>
  )
}

/**
 * Three-dock editor: item tree, canvas slot and a properties panel that follows
 * the selection. Owns selection, hover, dock visibility and the shortcuts; the
 * app owns the data and applies changes through `onUpdate`, `onRemove` and
 * `onRename`. Removals wait out an undo toast before `onRemove` is called.
 */
export function Inspector<T extends InspectorItem>(props: InspectorProps<T>) {
  const { status = "ready", error, onRetry } = props

  if (status === "loading") {
    return (
      <div className="h-full min-h-0">
        <LoadingState label="Loading items" />
      </div>
    )
  }
  if (status === "error") {
    return (
      <div className="h-full min-h-0">
        <ErrorState
          error={error ?? new Error("The items could not be loaded.")}
          onRetry={onRetry}
        />
      </div>
    )
  }
  return <Workspace {...props} />
}

import { useMemo, useRef, useState, type MouseEvent } from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { ChevronRightIcon } from "lucide-react"

import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"
import { cn } from "@/lib/utils"

import { buildRows } from "./tree-model"
import { TruncatedText } from "./truncated-text"
import type { InspectorItem } from "./types"

function RenameField({
  value,
  onFinish,
}: {
  value: string
  onFinish: (next: string | null, refocus: boolean) => void
}) {
  const done = useRef(false)
  const finish = (next: string | null, refocus: boolean) => {
    if (done.current) return
    done.current = true
    onFinish(next, refocus)
  }

  return (
    <Input
      autoFocus
      aria-label="Rename item"
      defaultValue={value}
      className="h-5 min-w-0 flex-1 rounded-sm px-1 py-0 text-sm md:text-sm"
      onFocus={(event) => event.currentTarget.select()}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
      onBlur={(event) => finish(event.currentTarget.value, false)}
      onKeyDown={(event) => {
        event.stopPropagation()
        if (event.key === "Enter") {
          event.preventDefault()
          finish(event.currentTarget.value, true)
        } else if (event.key === "Escape") {
          event.preventDefault()
          finish(null, true)
        }
      }}
    />
  )
}

/**
 * Indented, collapsible list of items with a roving tab stop. Reports
 * selection intent through `onSelect` along with the rows currently visible
 * (collapsed descendants excluded); the owner decides what is selected.
 * Arrow keys move the selection, left/right fold a row, F2 renames it.
 */
export function ItemTree<T extends InspectorItem>({
  items,
  selectedIds,
  onSelect,
  onRename,
}: {
  items: T[]
  selectedIds: string[]
  onSelect: (
    id: string,
    mode: "replace" | "range" | "toggle",
    visibleIds: string[]
  ) => void
  onRename?: (id: string, title: string) => void
}) {
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(
    () => new Set()
  )
  const [renamingId, setRenamingId] = useState<string | null>(null)
  const [focusId, setFocusId] = useState<string | null>(null)
  const rowEls = useRef(new Map<string, HTMLElement>())

  const rows = useMemo(() => buildRows(items, collapsed), [items, collapsed])
  const visibleIds = useMemo(() => rows.map((row) => row.item.id), [rows])
  const selected = useMemo(() => new Set(selectedIds), [selectedIds])
  const tabStopId =
    rows.find((row) => row.item.id === focusId)?.item.id ??
    rows.find((row) => selected.has(row.item.id))?.item.id ??
    rows[0]?.item.id

  const setFolded = (id: string, folded: boolean) =>
    setCollapsed((prev) => {
      const next = new Set(prev)
      if (folded) next.add(id)
      else next.delete(id)
      return next
    })

  const treeRef = useHotkeys<HTMLDivElement>(
    ["up", "down", "left", "right", "f2"],
    (event) => {
      const target = event.target
      if (!(target instanceof Element)) return
      const id = target.closest<HTMLElement>("[data-item-id]")?.dataset.itemId
      const index = rows.findIndex((row) => row.item.id === id)
      if (id === undefined || index < 0) return
      const row = rows[index]
      event.preventDefault()

      if (event.key === "ArrowUp" || event.key === "ArrowDown") {
        const next = rows[index + (event.key === "ArrowDown" ? 1 : -1)]
        if (!next) return
        onSelect(next.item.id, "replace", visibleIds)
        rowEls.current.get(next.item.id)?.focus()
      } else if (event.key === "ArrowLeft") {
        if (row.hasChildren && row.expanded) setFolded(id, true)
      } else if (event.key === "ArrowRight") {
        if (row.hasChildren && !row.expanded) setFolded(id, false)
      } else if (event.key === "F2" && onRename) {
        setRenamingId(id)
      }
    }
  )

  const finishRename = (id: string, next: string | null, refocus: boolean) => {
    setRenamingId(null)
    const title = next?.trim()
    const current = items.find((item) => item.id === id)
    if (title && current && title !== current.title) onRename?.(id, title)
    if (refocus) rowEls.current.get(id)?.focus()
  }

  const modeOf = (event: MouseEvent) =>
    event.shiftKey
      ? "range"
      : event.metaKey || event.ctrlKey
        ? "toggle"
        : "replace"

  return (
    <ScrollArea className="h-full [&_[data-slot=scroll-area-viewport]>div]:block!">
      <div
        ref={treeRef}
        role="tree"
        aria-label="Items"
        aria-multiselectable="true"
        className="flex flex-col gap-px p-1.5"
      >
        {rows.map(({ item, depth, hasChildren, expanded }) => {
          const isSelected = selected.has(item.id)
          return (
            <div
              key={item.id}
              ref={(el) => {
                if (el) rowEls.current.set(item.id, el)
                else rowEls.current.delete(item.id)
              }}
              role="treeitem"
              data-mini="row"
              aria-level={depth + 1}
              aria-selected={isSelected}
              aria-expanded={hasChildren ? expanded : undefined}
              data-item-id={item.id}
              tabIndex={item.id === tabStopId ? 0 : -1}
              onFocus={() => setFocusId(item.id)}
              onClick={(event) => onSelect(item.id, modeOf(event), visibleIds)}
              onDoubleClick={() => onRename && setRenamingId(item.id)}
              style={{ paddingLeft: 4 + depth * 14 }}
              className={cn(
                "flex h-7 cursor-default items-center gap-1 rounded-md pr-2 text-sm outline-none select-none focus-visible:ring-2 focus-visible:ring-ring",
                isSelected ? "bg-primary/10 font-medium" : "hover:bg-muted"
              )}
            >
              <span
                aria-hidden
                className="grid size-4 shrink-0 place-items-center text-muted-foreground"
                onClick={(event) => {
                  if (!hasChildren) return
                  event.stopPropagation()
                  setFolded(item.id, expanded)
                }}
              >
                {hasChildren ? (
                  <ChevronRightIcon
                    className={cn(
                      "size-3 transition-transform",
                      expanded && "rotate-90"
                    )}
                  />
                ) : null}
              </span>
              <span
                aria-hidden
                className={cn(
                  "grid size-4 shrink-0 place-items-center rounded-sm text-[10px] leading-none font-semibold uppercase",
                  isSelected
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-muted-foreground"
                )}
              >
                {item.type.charAt(0)}
              </span>
              {renamingId === item.id ? (
                <RenameField
                  value={item.title}
                  onFinish={(next, refocus) =>
                    finishRename(item.id, next, refocus)
                  }
                />
              ) : (
                <TruncatedText text={item.title} className="flex-1" />
              )}
            </div>
          )
        })}
      </div>
    </ScrollArea>
  )
}

import { useCallback, useMemo, useRef, useState, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
